const chatInput = String($json.chatInput ?? '');

// ── field extraction ────────────────────────────────────────────────
const listingId    = (chatInput.match(/\bbproperty-\d+\b/i)?.[0] ?? '').toLowerCase();
const locality     = (chatInput.match(/locality\s+([^,]+)/i)?.[1] ?? '').trim();
const buildingType = (chatInput.match(/building\s*type\s+([^,]+)/i)?.[1] ?? '').trim();
const area         = Number(chatInput.match(/area\s+([\d.]+)/i)?.[1] ?? 0);
const price        = Number(chatInput.match(/price\s+([\d.]+)/i)?.[1] ?? 0);

// ── SQL injection guard ─────────────────────────────────────────────
const sqlEsc = s => s.replace(/'/g, "''");
const localitySafe     = sqlEsc(locality);
const buildingTypeSafe = sqlEsc(buildingType);

const conditions = [];
if (locality)     conditions.push(`LOWER(locality)      = LOWER('${localitySafe}')`);
if (buildingType) conditions.push(`LOWER(building_type) = LOWER('${buildingTypeSafe}')`);
const whereClause = conditions.length > 0 ? conditions.join(' AND ') : '1=1';

// ── parse validation ────────────────────────────────────────────────
const parseErrors = [];
if (!price || price <= 0) parseErrors.push('price could not be parsed — expected "price <number> BDT"');
if (!area  || area  <= 0) parseErrors.push('area could not be parsed — expected "area <number> sqft"');

return {
  chatInput,
  listingId,
  locality,
  buildingType,
  localitySafe,
  buildingTypeSafe,
  whereClause,
  area,
  price,
  parseErrors,
  hasParseErrors: parseErrors.length > 0,
};

const row = $json;
const avgPrice       = Number(row.avg_price       ?? 0);
const stdPrice       = Number(row.std_price       ?? 0);
const avgArea        = Number(row.avg_area        ?? 0);
const stdArea        = Number(row.std_area        ?? 0);
const sampleSize     = Number(row.sample_size     ?? 0);
const submittedPrice = Number(row.submitted_price ?? 0);
const submittedArea  = Number(row.submitted_area  ?? 0);

const reasons = [];
let flagged = false;

// ── no comparables ────────────────────────────────────────────────────
if (sampleSize === 0) {
  reasons.push('no comparable listings found for this locality/building type');
  flagged = true;
}

// ── low sample size warning ───────────────────────────────────────────
if (sampleSize > 0 && sampleSize < 5) {
  reasons.push(`low comparable sample size (${sampleSize})`);
}

// ── price z-score ────────────────────────────────────────────────────
let zPrice = 0;
if (sampleSize > 0) {
  if (stdPrice === 0) {
    reasons.push('price has zero variance across comparables — z-score indeterminate; manual review required');
    flagged = true;
  } else {
    zPrice = (submittedPrice - avgPrice) / stdPrice;
    if (Math.abs(zPrice) > 2) {
      reasons.push(`price z-score ${zPrice.toFixed(2)} exceeds ±2 threshold`);
      flagged = true;
    }
  }
}

// ── area z-score ─────────────────────────────────────────────────────
let zArea = 0;
if (sampleSize > 0) {
  if (stdArea === 0) {
    reasons.push('area has zero variance across comparables — z-score indeterminate; manual review required');
    flagged = true;
  } else {
    zArea = (submittedArea - avgArea) / stdArea;
    if (Math.abs(zArea) > 2) {
      reasons.push(`area z-score ${zArea.toFixed(2)} exceeds ±2 threshold`);
      flagged = true;
    }
  }
}

// ── human-readable percentage deltas ─────────────────────────────────
// These give the LLM something concrete to phrase naturally, e.g.
// "the price is 45 % above the neighbourhood average".
const priceDeltaPct = avgPrice > 0
  ? (((submittedPrice - avgPrice) / avgPrice) * 100).toFixed(1)
  : null;
const areaDeltaPct  = avgArea  > 0
  ? (((submittedArea  - avgArea)  / avgArea)  * 100).toFixed(1)
  : null;

// ── context block for the LLM interpretation node ────────────────────
// Expressed entirely in plain numbers / percentages — no z-scores.
const llmContext = {
  listingId:       row.listing_id    || 'unknown',
  locality:        row.locality      || 'unknown',
  buildingType:    row.building_type || 'unknown',
  verdict:         flagged ? 'FLAGGED' : 'OK',
  sampleSize,

  // submitted values
  submittedPrice,
  submittedArea,

  // market averages (null when no comparables)
  avgPrice:       sampleSize > 0 ? avgPrice       : null,
  avgArea:        sampleSize > 0 ? avgArea        : null,

  // how far above/below the market average, as a percentage
  // positive = above average, negative = below average
  priceDeltaPct:  sampleSize > 0 && avgPrice > 0 ? Number(priceDeltaPct) : null,
  areaDeltaPct:   sampleSize > 0 && avgArea  > 0 ? Number(areaDeltaPct)  : null,

  // plain-English reason strings (already free of z-score language
  // where possible; the LLM will rephrase them further)
  reasons,

  // flags to guide the LLM's tone
  noComparables:     sampleSize === 0,
  lowSample:         sampleSize > 0 && sampleSize < 5,
  priceZeroVariance: sampleSize > 0 && stdPrice === 0,
  areaZeroVariance:  sampleSize > 0 && stdArea  === 0,
};

const verdict = flagged ? 'FLAGGED' : 'OK';

return {
  ...row,
  verdict,
  z_price:    zPrice,
  z_area:     zArea,
  reasons,
  llmContext: JSON.stringify(llmContext),   // serialised for the LLM prompt
};
